package vn.btl.teaching;
import java.util.*;
import org.springframework.dao.*;
import org.springframework.security.access.AccessDeniedException;
public final class Errors {
 private Errors(){}
 private static final Map<String,String> MESSAGES=Map.ofEntries(
 Map.entry("DUPLICATE_ENROLLMENT","Bạn đã đăng ký lớp này."),Map.entry("DUPLICATE_COURSE","Bạn đã đăng ký môn này ở lớp khác trong cùng học kỳ."),Map.entry("CLASS_FULL","Lớp đã đủ sĩ số. Vui lòng chọn lớp khác."),Map.entry("CLASS_NOT_OPEN","Lớp chưa mở hoặc đã đóng đăng ký."),Map.entry("REGISTRATION_CLOSED","Đã đến ngày bắt đầu học; không thể đăng ký thêm."),Map.entry("CANCELLATION_CLOSED","Đã đến ngày bắt đầu học; không thể hủy đăng ký."),Map.entry("NOT_OWNER","Đăng ký này không thuộc về bạn."),Map.entry("NOT_SECTION_LECTURER","Bạn không phụ trách lớp học phần này."),Map.entry("INVALID_SCORE","Điểm phải trong khoảng 0–10."),Map.entry("DUPLICATE_RECEIPT","Mã phiếu thu đã tồn tại. Kiểm tra lịch sử trước khi thu lại."),Map.entry("PAYMENT_EXCEEDS_BALANCE","Số tiền thu vượt quá công nợ còn lại."),Map.entry("NO_OUTSTANDING_BALANCE","Sinh viên không còn khoản nợ cần thu trong học kỳ này."),Map.entry("ENROLLMENT_NOT_ACTIVE","Đăng ký đã hủy; không thể thao tác."),Map.entry("ENROLLMENT_NOT_FOUND","Không tìm thấy đăng ký."),Map.entry("SECTION_NOT_FOUND","Không tìm thấy lớp học phần."),Map.entry("STUDENT_NOT_FOUND","Không tìm thấy sinh viên."),Map.entry("SEMESTER_NOT_FOUND","Không tìm thấy học kỳ."),Map.entry("STUDENT_ACCOUNT_INVALID","Tài khoản sinh viên đã khóa hoặc không hợp lệ."),Map.entry("LECTURER_ACCOUNT_INVALID","Tài khoản giảng viên đã khóa hoặc không hợp lệ."),Map.entry("COLLECTOR_ACCOUNT_INVALID","Tài khoản người thu không hợp lệ."),Map.entry("INVALID_AMOUNT","Số tiền thu không hợp lệ."),Map.entry("INVALID_RECEIPT","Mã phiếu thu không được để trống."),Map.entry("INVALID_ARGUMENT","Dữ liệu gửi lên chưa hợp lệ."),Map.entry("ENROLLMENT_CHANGED","Đăng ký vừa thay đổi; vui lòng tải lại trang."));
 public static String message(Throwable e){if(e instanceof AccessDeniedException)return "Bạn không có quyền thực hiện thao tác này.";if(e instanceof IllegalArgumentException)return e.getMessage();for(Throwable x=e;x!=null;x=x.getCause()){String text=String.valueOf(x.getMessage());for(var m:MESSAGES.entrySet())if(text.contains(m.getKey()))return m.getValue();}if(e instanceof DuplicateKeyException)return "Mã hoặc tên đăng nhập đã tồn tại. Vui lòng dùng giá trị khác.";if(e instanceof DataIntegrityViolationException)return "Không thể lưu/xóa vì dữ liệu không hợp lệ hoặc đang được tham chiếu. Kiểm tra lại các trường và liên kết.";return "Chưa xác nhận được kết quả. Hãy kiểm tra dữ liệu hoặc lịch sử phiếu thu trước khi thử lại; xem log máy chủ nếu lỗi tiếp diễn.";}
}
